package store

import("context";"database/sql";"fmt";"os";"path/filepath";"time";_ "modernc.org/sqlite")
type Store struct{DB *sql.DB}
func Open(path string)(*Store,error){if err:=os.MkdirAll(filepath.Dir(path),0o755);err!=nil{return nil,err};db,err:=sql.Open("sqlite",path+"?_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)");if err!=nil{return nil,err};db.SetMaxOpenConns(1);s:=&Store{DB:db};if err:=s.Migrate(context.Background());err!=nil{db.Close();return nil,err};return s,nil}
func(s *Store)Migrate(ctx context.Context)error{for i,migration:=range migrations{version:=i+1;var exists int;err:=s.DB.QueryRowContext(ctx,"SELECT COUNT(1) FROM schema_migrations WHERE version=?",version).Scan(&exists);if err!=nil&&i>0{return err};if i==0{if _,err:=s.DB.ExecContext(ctx,migration);err!=nil{return err};_=s.DB.QueryRowContext(ctx,"SELECT COUNT(1) FROM schema_migrations WHERE version=?",version).Scan(&exists)};if exists>0{continue};tx,err:=s.DB.BeginTx(ctx,nil);if err!=nil{return err};if _,err=tx.ExecContext(ctx,migration);err!=nil{tx.Rollback();return fmt.Errorf("migration %d: %w",version,err)};if _,err=tx.ExecContext(ctx,"INSERT INTO schema_migrations(version,applied_at) VALUES(?,?)",version,time.Now().UTC().Format(time.RFC3339Nano));err!=nil{tx.Rollback();return err};if err=tx.Commit();err!=nil{return err}};return nil}
func(s *Store)Close()error{return s.DB.Close()}
